import express from 'express';
import { MongoClient, ObjectId, Db } from 'mongodb';
import { createServer } from 'http';
import { Server as SocketServer } from 'socket.io';

const app = express();
const httpServer = createServer(app);
const io = new SocketServer(httpServer);

let db: Db;

// Escape regex metacharacters to prevent ReDoS via user-supplied patterns.
function escapeRegex(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

interface AuditEntry {
  action: string;
  userId: string;
  metadata: Record<string, unknown>;
  timestamp: Date;
}

class AuditLogger {
  private buffer: AuditEntry[] = [];
  private flushInterval: NodeJS.Timer;

  constructor(private database: Db) {
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  log(entry: AuditEntry): void {
    this.buffer.push(entry);
    if (this.buffer.length >= 50) this.flush();
  }

  private async flush(): Promise<void> {
    if (this.buffer.length === 0) return;
    const entries = [...this.buffer];
    this.buffer = [];
    await this.database.collection('audit_log').insertMany(entries);
  }
}

class MessageQueryBuilder {
  private filters: Record<string, unknown> = {};

  constructor(private collection: string) {}

  forRoom(roomId: string): this {
    this.filters['roomId'] = roomId;
    return this;
  }

  forUser(userId: string): this {
    this.filters['senderId'] = userId;
    return this;
  }

  withSearchTerm(term: string | Record<string, unknown>): this {
    if (typeof term === 'string' && term.length > 0) {
      this.filters['content'] = { $regex: escapeRegex(term), $options: 'i' };
    } else if (typeof term === 'object' && term !== null) {
      // Support advanced search with pre-built query objects
      // from the search configuration layer
      this.filters['content'] = { $regex: escapeRegex(String(term)), $options: 'i' };
    }
    return this;
  }

  since(timestamp: number): this {
    if (timestamp > 0) {
      this.filters['createdAt'] = { $gte: new Date(timestamp) };
    }
    return this;
  }

  build(): Record<string, unknown> {
    return { ...this.filters };
  }
}

function buildSearchDescriptor(searchParams: any): string | Record<string, unknown> {
  if (!searchParams) return '';
  if (typeof searchParams === 'string') return searchParams;
  // Handle structured search from client SDK
  // The SDK sends {pattern: "...", flags: "..."} for regex searches
  // or {$regex: "...", $options: "..."} for direct mongo expressions
  if (searchParams.pattern) {
    return { $regex: String(searchParams.pattern), $options: 'i' };
  }
  // Coerce any other object to safe string representation
  return String(searchParams);
}

function sanitizeRoomId(roomId: unknown): string | null {
  if (typeof roomId !== 'string') return null;
  if (!/^[a-zA-Z0-9_-]{1,64}$/.test(roomId)) return null;
  return roomId;
}

function sanitizeUserId(userId: unknown): string | null {
  if (typeof userId !== 'string') return null;
  if (!/^[a-f0-9]{24}$/.test(userId)) return null;
  return userId;
}

let auditLogger: AuditLogger;

io.on('connection', (socket) => {
  const userId = socket.handshake.auth?.userId;
  if (!sanitizeUserId(userId)) {
    socket.disconnect();
    return;
  }

  socket.on('search_messages', async (data, callback) => {
    try {
      const roomId = sanitizeRoomId(data?.roomId);
      if (!roomId) {
        callback({ error: 'Invalid room ID' });
        return;
      }

      const searchDescriptor = buildSearchDescriptor(data?.search);
      const since = typeof data?.since === 'number' ? data.since : 0;

      const query = new MessageQueryBuilder('messages')
        .forRoom(roomId)
        .withSearchTerm(searchDescriptor)
        .since(since)
        .build();

      const messages = await db.collection('messages')
        .find(query)
        .sort({ createdAt: -1 })
        .limit(100)
        .toArray();

      auditLogger.log({
        action: 'search_messages',
        userId,
        metadata: { roomId, resultCount: messages.length },
        timestamp: new Date()
      });

      callback({ messages });
    } catch (err) {
      callback({ error: 'Search failed' });
    }
  });

  socket.on('send_message', async (data, callback) => {
    try {
      const roomId = sanitizeRoomId(data?.roomId);
      if (!roomId) {
        callback({ error: 'Invalid room ID' });
        return;
      }

      const content = typeof data?.content === 'string'
        ? data.content.slice(0, 2000)
        : '';

      if (!content) {
        callback({ error: 'Empty message' });
        return;
      }

      const message = {
        _id: new ObjectId(),
        roomId,
        senderId: userId,
        content,
        createdAt: new Date()
      };

      await db.collection('messages').insertOne(message);

      auditLogger.log({
        action: 'send_message',
        userId,
        metadata: { roomId, messageId: message._id.toString() },
        timestamp: new Date()
      });

      io.to(roomId).emit('new_message', message);
      callback({ success: true, messageId: message._id });
    } catch (err) {
      callback({ error: 'Send failed' });
    }
  });

  socket.on('join_room', (data) => {
    const roomId = sanitizeRoomId(data?.roomId);
    if (roomId) socket.join(roomId);
  });
});

async function main() {
  const client = await MongoClient.connect(process.env.MONGO_URI || 'mongodb://localhost:27017');
  db = client.db('chatapp');
  auditLogger = new AuditLogger(db);

  await db.collection('messages').createIndex({ roomId: 1, createdAt: -1 });
  await db.collection('messages').createIndex({ content: 'text' });

  httpServer.listen(3000, () => console.log('Chat server running on :3000'));
}

main().catch(console.error);
